const query = ($('Webhook').first().json.body?.message || '').toLowerCase().replace(/^(profil negara|negara|country|profil|info)\s*/i, '').replace(/^["']|["']$/g, '').trim() || 'japan';
const list = Array.isArray($json) ? $json : [$json];

const matched = list.find(c => 
  c.name?.common?.toLowerCase() === query ||
  c.cca2?.toLowerCase() === query ||
  c.cca3?.toLowerCase() === query ||
  (c.capital && c.capital.some(cap => cap.toLowerCase() === query)) ||
  c.name?.common?.toLowerCase().includes(query)
) || list.find(c => c.name?.common?.toLowerCase() === 'japan');

const cap = matched.capital ? matched.capital.join(', ') : 'N/A';
const cur = matched.currencies ? Object.values(matched.currencies).map(c => `${c.name} (${c.symbol || '-'})`).join(', ') : 'N/A';
const lang = matched.languages ? Object.values(matched.languages).join(', ') : 'N/A';

let content = `🌍 **[PROFIL NEGARA: ${matched.flag || '🏳️'} ${matched.name.common.toUpperCase()}]**\n\n`;
content += `🏛️ **Nama Resmi:** *${matched.name.official}*\n`;
content += `- **Ibukota:** 📍 **${cap}**\n`;
content += `- **Kawasan:** 🗺️ **${matched.region} (${matched.subregion || ''})**\n`;
content += `- **Luas Wilayah:** 📐 **${matched.area ? matched.area.toLocaleString() + ' km²' : 'N/A'}**\n`;
content += `- **Bahasa Resmi:** 🗣️ **${lang}**\n`;
content += `- **Mata Uang:** 💵 **${cur}**\n`;
content += `- **Perbatasan:** 🧭 *${matched.borders && matched.borders.length > 0 ? matched.borders.join(', ') : 'Negara Kepulauan'}*\n`;

const chips = ['🇯🇵 Profil Negara "Japan"', '🇮🇩 Profil Negara "Indonesia"', '🇩🇪 Profil Negara "Germany"', '🇧🇷 Profil Negara "Brazil"'];
return { json: { content, chips } };
